pred_sql:
SELECT COUNT(*) AS n_billing_events 
FROM events 
WHERE event_type = 'billing_created';

SELECT COUNT(*) AS n_order_events 
FROM events 
WHERE event_type = 'order_created';

SELECT COUNT(*) AS n_payment_clearing_events 
FROM events 
WHERE event_type = 'payment_clearing';

SELECT COUNT(DISTINCT o.object_id) AS n 
FROM objects o 
WHERE o.object_type = 'order_item' 
  AND o.object_id IN (
    SELECT object_id FROM events WHERE event_type = 'goods_issue'
  )
  AND o.object_id IN (
    SELECT object_id FROM events WHERE event_type = 'billing_created'
  );

SELECT COUNT(*) AS n_pricing_condition_events 
FROM events 
WHERE event_type = 'pricing_condition';
